import React from 'react';
import { useParams, Link } from 'react-router-dom';
import { postsData } from '../posts'; // Importamos los datos de los posts
import '../styles/Blog.css'; // Reutilizamos los estilos del blog

const BlogPost = () => {
  const { slug } = useParams();
  const post = postsData.find(p => p.slug === slug);

  // Si no se encuentra el post, mostrar un mensaje
  if (!post) {
    return (
      <div className="blog-container">
        <div className="post-not-found">
          <h2>Artículo no encontrado 🧐</h2>
          <p>El artículo que buscas no existe o fue movido.</p>
          <Link to="/blog" className="pagina-btn-volver">← Volver al blog</Link>
        </div>
      </div>
    );
  }

  return (
    <div className="blog-container">
      <article className="blog-post-full">
        <div className="blog-video-container-full">
          <iframe
            className="blog-post-full-video"
            src={post.videoUrl}
            title={post.title}
            frameBorder="0"
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
            allowFullScreen
          ></iframe>
        </div>
        <h1 className="blog-post-full-title">{post.title}</h1>
        <div className="blog-post-full-meta">
          <span>Por {post.author}</span> | <span>{post.displayDate}</span>
        </div>
        <div 
          className="blog-post-full-content"
          dangerouslySetInnerHTML={{ __html: post.content }}
        />
        <Link to="/blog" className="pagina-btn-volver">
          ← Volver al blog
        </Link>
      </article>
    </div>
  );
};

export default BlogPost;
